import sys

MOD = 10**9 + 7
read = sys.stdin.readline

n_k = read().strip()
if not n_k:
    print(0)
    sys.exit(0)
n, k = map(int, n_k.split())
g = [[] for _ in range(n + 1)]
for _ in range(n - 1):
    u, v = map(int, read().split())
    g[u].append(v)
    g[v].append(u)

if n % 2 == 1:
    print(0)
    sys.exit(0)

# 迭代 DFS：求父亲、遍历顺序
parent = [0] * (n + 1)
order = []
st = [1]
parent[1] = -1
while st:
    u = st.pop()
    order.append(u)
    for v in g[u]:
        if v == parent[u]:
            continue
        parent[v] = u
        st.append(v)

# 逆序累加子树大小
sz = [1] * (n + 1)
for u in reversed(order):
    p = parent[u]
    if p != -1:
        sz[p] += sz[u]

# 统计偶子树边数
m = 0
for v in range(2, n + 1):
    if sz[v] % 2 == 0:
        m += 1

# 组合数 C(m, k)
if k > m:
    print(0)
    sys.exit(0)

# 预处理阶乘与逆元（到 n 即可）
fac = [1] * (n + 1)
for i in range(1, n + 1):
    fac[i] = fac[i - 1] * i % MOD

def mod_pow(a, e):
    r = 1
    while e:
        if e & 1:
            r = r * a % MOD
        a = a * a % MOD
        e >>= 1
    return r

inv_fac = [1] * (n + 1)
inv_fac[n] = mod_pow(fac[n], MOD - 2)
for i in range(n - 1, -1, -1):
    inv_fac[i] = inv_fac[i + 1] * (i + 1) % MOD

def C(nv, kv):
    if kv < 0 or kv > nv:
        return 0
    return fac[nv] * inv_fac[kv] % MOD * inv_fac[nv - kv] % MOD

print(C(m, k))
```

