MOD = 10**9 + 7

def mod_pow(a, e):
    r = 1
    while e:
        if e & 1:
            r = r * a % MOD
        a = a * a % MOD
        e >>= 1
    return r

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    # 构建邻接表
    g = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(it))
        v = int(next(it))
        g[u].append(v)
        g[v].append(u)

    # 总数为奇数时无解
    if n % 2 == 1:
        print(0)
        return

    # 迭代 DFS 获取父节点和遍历顺序
    parent = [0] * (n + 1)
    order = []
    stack = [1]
    parent[1] = -1
    while stack:
        u = stack.pop()
        order.append(u)
        for v in g[u]:
            if v == parent[u]:
                continue
            parent[v] = u
            stack.append(v)

    # 逆序累加子树大小
    sz = [1] * (n + 1)
    for u in reversed(order):
        p = parent[u]
        if p != -1:
            sz[p] += sz[u]

    # 统计偶子树边数 m (不含根)
    m = sum(1 for v in range(2, n + 1) if sz[v] % 2 == 0)

    if k > m:
        print(0)
        return

    # 预处理阶乘与逆元
    fac = [1] * (n + 1)
    for i in range(1, n + 1):
        fac[i] = fac[i - 1] * i % MOD

    inv_fac = [1] * (n + 1)
    inv_fac[n] = mod_pow(fac[n], MOD - 2)
    for i in range(n - 1, -1, -1):
        inv_fac[i] = inv_fac[i + 1] * (i + 1) % MOD

    def C(N, K):
        if K < 0 or K > N:
            return 0
        return fac[N] * inv_fac[K] % MOD * inv_fac[N - K] % MOD

    print(C(m, k))

if __name__ == "__main__":
    solve()
